import { Router, Response } from "express";
import { AuthRequest, requireAuth } from "../middleware/auth";
import {
  UserSecurityError,
  heartbeatSession,
  listSessions,
  revokeAllSessions,
  revokeSession,
  startSession,
} from "../services/userSecurity";

/**
 * Device list + remote sign-out.
 *
 * Mounted at /api/users/sessions. The device id is generated by the app and
 * persists across launches; it is NOT a secret and never authorises anything
 * on its own — every route still requires a Firebase token.
 */
const router = Router();

function fail(res: Response, err: any, fallback: string): void {
  if (err instanceof UserSecurityError) {
    res.status(err.statusCode).json({ error: err.message, code: err.code });
    return;
  }
  console.error(`[user-sessions] ${fallback}:`, err?.message || err);
  res.status(500).json({ error: fallback });
}

function bodyDeviceId(req: AuthRequest): string {
  return String(req.body?.deviceId || req.query?.deviceId || "").trim();
}

// POST /api/users/sessions/start — called after a successful sign-in and after
// the 2FA challenge. Re-registers this device and clears a previous revoke so
// a legitimate new login works; heartbeats never clear a revoke.
router.post("/start", requireAuth, async (req: AuthRequest, res: Response) => {
  try {
    const result = await startSession(req.userId!, {
      deviceId: bodyDeviceId(req),
      platform: String(req.body?.platform || ""),
      app: String(req.body?.app || ""),
      appVersion: req.body?.appVersion ? String(req.body.appVersion) : null,
      deviceName: req.body?.deviceName ? String(req.body.deviceName) : null,
      ip: req.ip,
      authTime: req.authTime,
    });
    res.status(201).json(result);
  } catch (err) {
    fail(res, err, "Could not register this device");
  }
});

// POST /api/users/sessions/heartbeat — keeps "last seen" current and catches a
// remote revoke. Never re-activates a revoked device.
router.post("/heartbeat", requireAuth, async (req: AuthRequest, res: Response) => {
  try {
    await heartbeatSession(
      req.userId!,
      bodyDeviceId(req),
      req.body?.appVersion ? String(req.body.appVersion) : undefined
    );
    res.json({ ok: true });
  } catch (err) {
    fail(res, err, "Could not update this device");
  }
});

// GET /api/users/sessions — the devices currently signed in.
router.get("/", requireAuth, async (req: AuthRequest, res: Response) => {
  try {
    const sessions = await listSessions(req.userId!, bodyDeviceId(req));
    res.json({ sessions });
  } catch (err) {
    fail(res, err, "Could not load your devices");
  }
});

// POST /api/users/sessions/revoke — sign out ONE device. If it is the current
// device the app clears its own session after the response.
router.post("/revoke", requireAuth, async (req: AuthRequest, res: Response) => {
  try {
    const sessionId = String(req.body?.sessionId || "").trim();
    if (!sessionId) {
      res.status(400).json({ error: "sessionId is required", code: "missing_session" });
      return;
    }
    const result = await revokeSession(req.userId!, sessionId, bodyDeviceId(req) || undefined);
    res.json(result);
  } catch (err) {
    fail(res, err, "Could not sign out that device");
  }
});

// POST /api/users/sessions/revoke-all — the stolen-phone button. Marks every
// device revoked, sets the per-user token cutoff and revokes Firebase refresh
// tokens. Every device (including this one) must sign in again.
router.post("/revoke-all", requireAuth, async (req: AuthRequest, res: Response) => {
  try {
    const result = await revokeAllSessions(req.userId!, bodyDeviceId(req) || null);
    res.json(result);
  } catch (err) {
    fail(res, err, "Could not sign out your devices");
  }
});

export default router;
